                transcript_sha256=str(payload["transcript_sha256"]),
                judge_model=str(payload["judge_model"]),
                judge_base_url=_canonical_judge_base_url(str(payload["judge_base_url"])),
                judge_max_tokens=int(payload["judge_max_tokens"]),
