    DistributedOperator,
    DistributedVaeMixin,
    GridSpec,
    TileTask,
)
from vllm_omni.diffusion.distributed.autoencoders.wan_vae_fastpath import (
    can_encode_frames,
    decode_frames,
    encode_frames,
    is_encoder_installed,
    is_installed,
