def _worker_env(od_config: OmniDiffusionConfig) -> dict[str, str]:
    """Copy inference settings, keeping worker identity local to each actor."""
    prefixes = (
        "VLLM_",
        "OMNI_",
        "DIFFUSION_",
        "NCCL_",
        "TORCH_NCCL_",
        "UCX_",
