def _wan_decode_cache_bytes(decoder: nn.Module, height: int, width: int, dtype: torch.dtype) -> int:
    """Bound Wan2.2 causal features without allocating or running the decoder.

    Every cached convolution input retains at most two temporal slices. Count
    residual inputs at their own spatial stage, not decoder weights or outputs.
    This is checked against real streaming state in the two-session benchmark.
    """
    area = height * width
    elements = decoder.conv_in.in_channels * area
    for resnet in decoder.mid_block.resnets:
        elements += (resnet.conv1.in_channels + resnet.conv2.in_channels) * area
    for block in decoder.up_blocks:
        for resnet in block.resnets:
            elements += (resnet.conv1.in_channels + resnet.conv2.in_channels) * area
        if block.upsampler is not None:
            if block.upsampler.mode == "upsample3d":
                elements += block.upsampler.time_conv.in_channels * area
            area *= 4
    elements += decoder.conv_out.in_channels * area
    # CUDA autocast can retain FP32 normalized activations even when the VAE
    # weights are BF16. Admission must budget those features, not weight dtype.
    return 2 * elements * max(dtype.itemsize, torch.float32.itemsize)


def _paged_kv_tokens_per_frame(
    height: int,
    width: int,
    *,
    vae_scale_factor: int,
    patch_height: int,
    patch_width: int,
) -> int:
    """Return one frame's DiT token count and enforce FA page alignment."""
    divisor_h = vae_scale_factor * patch_height
    divisor_w = vae_scale_factor * patch_width
    if height % divisor_h or width % divisor_w:
        raise ValueError(
            "height/width must align with the VAE and DiT patch sizes: "
            f"height must be divisible by {divisor_h}, width by {divisor_w}."
        )
    tokens_per_frame = (height // divisor_h) * (width // divisor_w)
    if tokens_per_frame % _PAGED_KV_BLOCK_ALIGNMENT:
        raise ValueError(
            "ABot FlashAttention paged KV requires tokens_per_frame to be a "
            f"multiple of {_PAGED_KV_BLOCK_ALIGNMENT}, got {tokens_per_frame} "
            f"for {height}x{width}. Use 512x832 for the bundled Wan2.2 VAE."
        )
    return tokens_per_frame


def _validate_latent_channel_contract(
    *,
    vae_z_dim: int,
    transformer_in_channels: int,
    transformer_out_channels: int,
) -> None:
    """Reject a Wan VAE/DiT mismatch before the first expensive forward."""
    if vae_z_dim != transformer_in_channels or vae_z_dim != transformer_out_channels:
        raise ValueError(
