            f"VAE z_dim={vae_z_dim}, transformer in/out="
            f"{transformer_in_channels}/{transformer_out_channels}. "
            "ABot-World-0-5B-LF requires the 48-channel Wan2.2 TI2V-5B VAE."
        )


def _validate_latent_tensor(
